pub fn royalty_claim(usage: [u64; 8], specs: [u32; 16], authors: [u64; 16], lines: [u64; 16], tests: [u64; 16], flags: [u8; 16], id: u64) -> u64 {
    let mut c: u64 = 0;
    let mut s: u32 = 0;
    while (s < USAGE_SPECS) {
        c = (c + (royalty_usage(usage[(s) as usize]) * weight_of(specs, authors, lines, tests, flags, s, id)));
        s = (s + 1);
    }
    return c;
}

pub fn royalty_first_id(specs: [u32; 16], authors: [u64; 16], flags: [u8; 16], i: u32) -> bool {
    if (specs[(i) as usize] == NO_SPEC) {
        return false;
    }
    let c: u64 = credited_to(authors[(i) as usize], flags[(i) as usize]);
    let mut j: u32 = 0;
    while (j < i) {
        if ((specs[(j) as usize] != NO_SPEC) && (credited_to(authors[(j) as usize], flags[(j) as usize]) == c)) {
            return false;
        }
        j = (j + 1);
    }
    return true;
}

pub fn royalty_floor(pool: u64, claim: u64, total: u64) -> u64 {
    if (total == 0) {
        return 0;
    }
    let q: u64 = (pool / total);
    let r: u64 = (pool - (q * total));
    return ((q * claim) + ((r * claim) / total));
}

pub fn royalty_held_total(pool: u64, usage: [u64; 8], specs: [u32; 16], authors: [u64; 16], lines: [u64; 16], tests: [u64; 16], flags: [u8; 16]) -> u64 {
    let mut h: u64 = 0;
    let mut i: u32 = 0;
    while (i < ATTR_ROWS) {
        let c: u64 = credited_to(authors[(i) as usize], flags[(i) as usize]);
        if (royalty_first_id(specs, authors, flags, i) && is_held(c)) {
            h = (h + royalty_floor(pool, royalty_claim(usage, specs, authors, lines, tests, flags, c), royalty_total(usage)));
        }
        i = (i + 1);
    }
    return h;
}

pub fn royalty_share(pool: u64, usage: [u64; 8], specs: [u32; 16], authors: [u64; 16], lines: [u64; 16], tests: [u64; 16], flags: [u8; 16], id: u64) -> u64 {
    if (payable(id) == false) {
        return 0;
    }
    return royalty_floor(pool, royalty_claim(usage, specs, authors, lines, tests, flags, id), royalty_total(usage));
}

pub fn royalty_total(usage: [u64; 8]) -> u64 {
    let mut t: u64 = 0;
    let mut s: u32 = 0;
    while (s < USAGE_SPECS) {
        t = (t + (royalty_usage(usage[(s) as usize]) * BP_TOTAL));
        s = (s + 1);
    }
    return t;
}

pub fn royalty_usage(u: u64) -> u64 {
    if (u > USAGE_MAX) {
        return USAGE_MAX;
    }
    return u;
}

pub fn usage_bit(auth: u8, b: u8) -> bool {
    return ((auth & b) != 0);
}

pub fn usage_commit_epoch(commits: [u64; 8], epochs: [u64; 8], auths: [u8; 8], nonces: [u8; 8], commit: u64) -> u64 {
    let mut e: u64 = NO_EPOCH;
    let mut i: u32 = 0;
    while (i < USAGE_ROWS) {
        if (((commits[(i) as usize] == commit) && usage_counts(commits[(i) as usize], auths[(i) as usize], nonces[(i) as usize])) && (epochs[(i) as usize] < e)) {
            e = epochs[(i) as usize];
        }
        i = (i + 1);
    }
    return e;
}

pub fn usage_counts(commit: u64, auth: u8, nonce: u8) -> bool {
    if (commit == NO_COMMIT) {
        return false;
    }
    if (usage_bit(auth, U_KEY_REGISTERED) == false) {
        return false;
    }
    return (usage_level(auth, nonce) >= LEVEL_AUTHOR);
}

pub fn usage_key_first(commits: [u64; 8], keys: [u64; 8], epochs: [u64; 8], auths: [u8; 8], nonces: [u8; 8], reads: [u64; 8], i: u32, spec: u32) -> bool {
    if (usage_row_reads(commits, epochs, auths, nonces, reads, i, spec) == false) {
        return false;
    }
    let mut j: u32 = 0;
    while (j < i) {
        if (((commits[(j) as usize] == commits[(i) as usize]) && (keys[(j) as usize] == keys[(i) as usize])) && usage_row_reads(commits, epochs, auths, nonces, reads, j, spec)) {
            return false;
        }
        j = (j + 1);
    }
    return true;
}

pub fn usage_keys_reading(commits: [u64; 8], keys: [u64; 8], epochs: [u64; 8], auths: [u8; 8], nonces: [u8; 8], reads: [u64; 8], commit: u64, spec: u32) -> u64 {
    let mut n: u64 = 0;
    let mut i: u32 = 0;
    while (i < USAGE_ROWS) {
        if ((commits[(i) as usize] == commit) && usage_key_first(commits, keys, epochs, auths, nonces, reads, i, spec)) {
            n = (n + 1);
        }
        i = (i + 1);
    }
    return n;
}

pub fn usage_level(auth: u8, nonce: u8) -> u8 {
    return receipt_level(usage_bit(auth, U_SIGNED), usage_bit(auth, U_KEY_REGISTERED), usage_bit(auth, U_SIGNATURE_VALID), usage_bit(auth, U_CHALLENGE_GIVEN), nonce, usage_bit(auth, U_NONCE_IS_CHALLENGE));
}

pub fn usage_of(commits: [u64; 8], keys: [u64; 8], epochs: [u64; 8], auths: [u8; 8], nonces: [u8; 8], reads: [u64; 8], spec: u32, epoch: u64) -> u64 {
    let mut u: u64 = 0;
    let mut i: u32 = 0;
    while (i < USAGE_ROWS) {
        if ((epochs[(i) as usize] == epoch) && usage_use_first(commits, keys, epochs, auths, nonces, reads, i, spec)) {
            u = (u + usage_weight(usage_keys_reading(commits, keys, epochs, auths, nonces, reads, commits[(i) as usize], spec)));
        }
        i = (i + 1);
    }
    return u;
}

pub fn usage_reads(mask: u64, spec: u32) -> bool {
    if (spec >= 64) {
        return false;
    }
    return (((mask >> (spec as u64)) & 1) == 1);
}

pub fn usage_row_reads(commits: [u64; 8], epochs: [u64; 8], auths: [u8; 8], nonces: [u8; 8], reads: [u64; 8], i: u32, spec: u32) -> bool {
    if (usage_counts(commits[(i) as usize], auths[(i) as usize], nonces[(i) as usize]) == false) {
        return false;
    }
    if (usage_reads(reads[(i) as usize], spec) == false) {
        return false;
    }
    return (epochs[(i) as usize] == usage_commit_epoch(commits, epochs, auths, nonces, commits[(i) as usize]));
}

pub fn usage_use_first(commits: [u64; 8], keys: [u64; 8], epochs: [u64; 8], auths: [u8; 8], nonces: [u8; 8], reads: [u64; 8], i: u32, spec: u32) -> bool {
    if (usage_key_first(commits, keys, epochs, auths, nonces, reads, i, spec) == false) {
        return false;
    }
    let mut j: u32 = 0;
    while (j < i) {
        if ((commits[(j) as usize] == commits[(i) as usize]) && usage_key_first(commits, keys, epochs, auths, nonces, reads, j, spec)) {
            return false;
        }
        j = (j + 1);
    }
    return true;
}

pub fn usage_weight(keys_reading: u64) -> u64 {
    if (keys_reading > QUORUM_CAP) {
        return QUORUM_CAP;
    }
    return keys_reading;
}

pub const LAB_URL: &'static str = "https://t27b-lab-production.up.railway.app/";

pub const RECEIPT_EXT: &'static str = ".receipt.json";

pub const RUNS: &'static str = "runs/";

pub const V_BEHIND: u8 = 2;

pub const V_BLOCKED: u8 = 3;

pub const V_NOT_RUN: u8 = 4;

pub const V_RED: u8 = 5;

pub const V_VACUOUS: u8 = 1;

pub const V_VERIFIED: u8 = 0;

pub fn key_at(text: &'static str, from: usize, stop: usize, ind: usize, key: &'static str) -> usize {
    let mut at: usize = from;
    while ((at < stop) && (at < text.len())) {
        let end: usize = line_end(text, at);
        let v: usize = key_value(text, at, end, ind, key);
        if (v <= end) {
            return v;
        }
        at = (end + 1);
    }
    return (text.len() + 1);
}

pub fn key_value(text: &'static str, at: usize, end: usize, ind: usize, key: &'static str) -> usize {
    let v: usize = (((at + ind) + key.len()) + 4);
    if (v > end) {
        return (end + 1);
    }
    let mut k: usize = 0;
    while (k < ind) {
        if (text.as_bytes()[((at + k)) as usize] != 32) {
            return (end + 1);
        }
        k = (k + 1);
    }
    if (text.as_bytes()[((at + ind)) as usize] != 34) {
        return (end + 1);
    }
    if (span_is(text, ((at + ind) + 1), (((at + ind) + 1) + key.len()), key) == false) {
        return (end + 1);
    }
    if (((text.as_bytes()[((v - 3)) as usize] != 34) || (text.as_bytes()[((v - 2)) as usize] != 58)) || (text.as_bytes()[((v - 1)) as usize] != 32)) {
        return (end + 1);
    }
    return v;
}

pub fn line_end(text: &'static str, at: usize) -> usize {
    let mut k: usize = at;
    while ((k < text.len()) && (text.as_bytes()[(k) as usize] != 10)) {
        k = (k + 1);
    }
    return k;
}

pub fn line_is(text: &'static str, at: usize, end: usize, ind: usize, lit: &'static str) -> bool {
    let mut e: usize = end;
    if ((e > at) && (text.as_bytes()[((e - 1)) as usize] == 44)) {
        e = (e - 1);
    }
    if (e < (at + ind)) {
        return false;
    }
    let mut k: usize = 0;
    while (k < ind) {
        if (text.as_bytes()[((at + k)) as usize] != 32) {
            return false;
        }
        k = (k + 1);
    }
    return span_is(text, (at + ind), e, lit);
}

pub fn name(v: u8) -> &'static str {
    if (v == V_VERIFIED) {
        return "verified";
    }
    if (v == V_VACUOUS) {
        return "vacuous";
    }
    if (v == V_BEHIND) {
        return "behind";
    }
    if (v == V_BLOCKED) {
        return "blocked";
    }
    if (v == V_NOT_RUN) {
        return "not-run";
    }
    if (v == V_RED) {
        return "RED";
    }
    return "UNREAD";
}

pub fn span_is(text: &'static str, from: usize, to: usize, lit: &'static str) -> bool {
    if ((to < from) || ((to - from) != lit.len())) {
        return false;
    }
    let mut k: usize = 0;
    while (k < lit.len()) {
        if (text.as_bytes()[((from + k)) as usize] != lit.as_bytes()[(k) as usize]) {
            return false;
        }
        k = (k + 1);
    }
    return true;
}

pub fn value_from(text: &'static str, v: usize) -> usize {
    if (v >= text.len()) {
        return text.len();
    }
    if (text.as_bytes()[(v) as usize] == 34) {
        return (v + 1);
    }
    return v;
}

pub fn value_to(text: &'static str, v: usize) -> usize {
    if (v >= text.len()) {
        return text.len();
    }
    let mut e: usize = line_end(text, v);
    if ((e > v) && (text.as_bytes()[((e - 1)) as usize] == 44)) {
        e = (e - 1);
    }
    if (((text.as_bytes()[(v) as usize] == 34) && (e > (v + 1))) && (text.as_bytes()[((e - 1)) as usize] == 34)) {
        e = (e - 1);
    }
    if (e < value_from(text, v)) {
        return value_from(text, v);
    }
    return e;
}

pub const LANE_EQUIVALENT: u8 = 0;

pub const AUTH_BAD_SIGNATURE: u8 = 3;

pub const AUTH_KEY_NOT_REGISTERED: u8 = 2;

pub const AUTH_MISSING_NONE: u8 = 0;

pub const AUTH_NONCE_NOT_CHALLENGE: u8 = 5;

pub const AUTH_NO_NONCE: u8 = 4;

pub const AUTH_UNSIGNED: u8 = 1;

pub const HEX_NOT_A_DIGIT: u32 = 16;

pub const LEVEL_AUTHOR: u8 = 1;

pub const LEVEL_FRESH: u8 = 2;

pub const LEVEL_NONE: u8 = 0;

pub const NONCE_MIN_BYTES: u8 = 16;

pub fn auth_first_missing(signed: bool, key_registered: bool, signature_valid: bool, challenge_given: bool, nonce_bytes: u8, nonce_is_challenge: bool) -> u8 {
    if (signed == false) {
        return AUTH_UNSIGNED;
    }
    if (key_registered == false) {
        return AUTH_KEY_NOT_REGISTERED;
    }
    if (signature_valid == false) {
        return AUTH_BAD_SIGNATURE;
    }
    if challenge_given {
        if (nonce_long_enough(nonce_bytes) == false) {
            return AUTH_NO_NONCE;
        }
        if (nonce_is_challenge == false) {
            return AUTH_NONCE_NOT_CHALLENGE;
        }
    }
    return AUTH_MISSING_NONE;
}

pub fn hex_digit_value(c: u32) -> u32 {
    if (c >= 48) {
        if (c <= 57) {
            return (c - 48);
        }
    }
    if (c >= 97) {
        if (c <= 102) {
            return (c - 87);
        }
    }
    if (c >= 65) {
        if (c <= 70) {
            return (c - 55);
        }
    }
    return HEX_NOT_A_DIGIT;
}

pub fn nonce_long_enough(nonce_bytes: u8) -> bool {
    return (nonce_bytes >= NONCE_MIN_BYTES);
}

pub fn receipt_level(signed: bool, key_registered: bool, signature_valid: bool, challenge_given: bool, nonce_bytes: u8, nonce_is_challenge: bool) -> u8 {
    let mut code: u8 = auth_first_missing(signed, key_registered, signature_valid, challenge_given, nonce_bytes, nonce_is_challenge);
    if (code == AUTH_UNSIGNED) {
        return LEVEL_NONE;
    }
    if (code == AUTH_KEY_NOT_REGISTERED) {
        return LEVEL_NONE;
    }
    if (code == AUTH_BAD_SIGNATURE) {
        return LEVEL_NONE;
    }
    if (challenge_given == false) {
        return LEVEL_AUTHOR;
    }
    if (code == AUTH_MISSING_NONE) {
        return LEVEL_FRESH;
    }
    return LEVEL_AUTHOR;
}

